import React from "react";
import "./Clients.css";


const InvoiceSummary = () => {
  // Datos temporales (mock)
  const invoice = {
    companyName: "Empresa Demo S.A.",
    invoiceNumber: "00001010929",
    period: "Desde siempre",
    description:
      "Descripción de ejemplo que viene desde el API. Este texto puede tener más contenido según sea necesario.",
    currency: "Dólar US",
    total: "1500.00",
    tax: "240.00",
    subtotal: "1260.00",
  };

  return (
    <div>
      <h2>{invoice.companyName}</h2>

      <p>
        <strong>Número Invoice:</strong> {invoice.invoiceNumber}
      </p>

      <p>
        <strong>Período:</strong> {invoice.period}
      </p>

      <p>{invoice.description}</p>

      <p>
        <strong>Tipo de moneda:</strong> {invoice.currency}
      </p>

      <p>
        <strong>Total:</strong> ${invoice.total}
      </p>

      <p>
        <strong>Tax:</strong> ${invoice.tax}
      </p>

      <p>
        <strong>Subt:</strong> ${invoice.subtotal}
      </p>

      <div>
        <img
          src={invoice.imageUrl}
          alt="Comprobante"
          width="100%"
        />
      </div>
    </div>
  );
};

export default InvoiceSummary;
